import React, { useState, useEffect } from 'react';
import './../styles/Modal.css'; 

const Modal = ({ content, closeModal }) => {
  const [currentImageIndex, setCurrentImageIndex] = useState(0);

  useEffect(() => {
    setCurrentImageIndex(0); // Reset index when content changes
  }, [content]);

  const goToNextSlide = () => {
    setCurrentImageIndex((prevIndex) =>
      prevIndex === content.images.length - 1 ? 0 : prevIndex + 1
    );
  };

  const goToPrevSlide = () => {
    setCurrentImageIndex((prevIndex) =>
      prevIndex === 0 ? content.images.length - 1 : prevIndex - 1
    );
  };

  if (!content || !content.text) {
    return null; // Don't render if no content
  }

  return (
    <div className={`modal ${content && content.text ? 'open' : ''}`}>
      <div className="modal-content">
        <div className="modal-left">
          {content.carousel && content.images && content.images.length > 0 ? (
            <div className="carousel-container">
              {content.images.map((image, index) => (
                <div
                  className={`carousel-slide ${
                    index === currentImageIndex ? 'active' : ''
                  }`}
                  key={index}
                >
                  <img src={content.images[index]} alt={`Slide ${index + 1}`} />
                </div>
              ))}
              {content.images.length > 1 && (
                <>
                  <button className="prev" onClick={goToPrevSlide}>
                    &lt;
                  </button>
                  <button className="next" onClick={goToNextSlide}>
                    &gt;
                  </button>
                </>
              )}
            </div>
          ) : (
            content.image && <img id="modalImg" src={content.image} alt="Modal" />
          )}
        </div>
        <div className="modal-right">
          <div className="text-content">
            <p>{content.text}</p>
          </div>
        </div>
        <button className="close-button" onClick={closeModal}>
          x
        </button>
      </div>
    </div>
  );
};

export default Modal;
